fetch('http://localhost:8080/api/route/map', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
  },
  body: JSON.stringify({
    locations: ['北京天安门', '故宫博物院', '景山公园'],
    strategy: 'walking',
    includeSteps: true
  })
})
.then(response => response.json())
.then(data => {
  console.log('地图生成成功:', data);
  console.log('地图URL:', data.data.mapUrl);
})
.catch(error => {
  console.error('请求失败:', error);
});
